def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)

    # Find uniform 5x5 colored blocks.
    blocks = []
    for r in range(h - 4):
        for c in range(w - 4):
            color = grid[r][c]
            if color != bg and all(
                grid[y][x] == color
                for y in range(r, r + 5)
                for x in range(c, c + 5)
            ):
                blocks.append((r, c, color))

    if not blocks:
        return grid

    r0 = max(0, min(r for r, c, color in blocks) - 1)
    r1 = min(h, max(r + 5 for r, c, color in blocks) + 1)
    c0 = max(0, min(c for r, c, color in blocks) - 1)
    c1 = min(w, max(c + 5 for r, c, color in blocks) + 1)
    out = [row[c0:c1] for row in grid[r0:r1]]

    for br, bc, color in blocks:
        motif = None
        best_count = 0
        for r in range(h - 2):
            for c in range(w - 2):
                # The motif must be outside all large blocks.
                if any(not (r + 2 < y or r > y + 4 or c + 2 < x or c > x + 4)
                       for y, x, _ in blocks):
                    continue
                vals = [grid[y][x]
                        for y in range(r, r + 3)
                        for x in range(c, c + 3)]
                if all(v == bg or v == color for v in vals):
                    n = sum(v == color for v in vals)
                    if n > best_count:
                        best_count = n
                        motif = (r, c)

        if motif is not None:
            mr, mc = motif
            for dy in range(3):
                for dx in range(3):
                    if grid[mr + dy][mc + dx] == color:
                        out[br + 1 + dy - r0][bc + 1 + dx - c0] = bg

    return out
